#include "common.hpp"
struct Row {size_t line;std::vector<std::string> cells;};
std::vector<Row> csv(const std::string&s){std::vector<Row> rows;std::vector<std::string> cells;std::string value;size_t line=1,start=1;bool quoted=false,closed=false,touched=false;auto endrow=[&](){if(touched||!cells.empty()||!value.empty()){cells.push_back(value);rows.push_back({start,cells});if(rows.size()>50001)throw std::runtime_error("CSV exceeds 50,000 data rows");}cells.clear();value.clear();closed=false;touched=false;};for(size_t i=0;i<s.size();++i){char c=s[i];if(quoted){if(c=='"'){if(i+1<s.size()&&s[i+1]=='"'){value+='"';++i;}else{quoted=false;closed=true;}}else{value+=c;if(c=='\n')++line;else if(c=='\r'&&(i+1==s.size()||s[i+1]!='\n'))++line;}continue;}if(c==','){cells.push_back(value);value.clear();closed=false;touched=true;continue;}if(c=='\r'||c=='\n'){if(c=='\r'&&i+1<s.size()&&s[i+1]=='\n')++i;endrow();++line;start=line;continue;}if(closed)throw std::runtime_error("Unexpected character after closing quote at line "+std::to_string(line));if(c=='"'){if(!value.empty())throw std::runtime_error("Quote inside an unquoted field at line "+std::to_string(line));quoted=true;touched=true;}else{value+=c;touched=true;}}if(quoted)throw std::runtime_error("Unclosed quoted field starting at line "+std::to_string(start));endrow();return rows;}
int main(int argc,char**argv){Report r;try{auto a=arguments(argc,argv);auto rows=csv(read_text(a.input));if(rows.empty())throw std::runtime_error("CSV is empty; a header row is required");std::unordered_map<std::string,size_t> index;for(size_t i=0;i<rows[0].cells.size();++i){auto h=trim(rows[0].cells[i]);if(h.empty())r.error(rows[0].line,"","CSV header contains an empty name");if(!index.emplace(h,i).second)r.error(rows[0].line,h,"Duplicate header name");r.fields.push_back(h);}r.read=rows.size()-1;for(size_t i=1;i<rows.size();++i)if(rows[i].cells.size()!=r.fields.size())r.error(rows[i].line,"","Expected "+std::to_string(r.fields.size())+" fields, found "+std::to_string(rows[i].cells.size()));if(a.inspect){r.print();return r.errors.empty()?0:2;}auto mapping=a.map.empty()?std::vector<Mapping>{}:read_map(a.map);if(mapping.empty())for(const auto&h:r.fields)mapping.push_back({h,h,"string",false});std::unordered_set<std::string> selected;for(auto&m:mapping){selected.insert(m.source);if(!index.count(m.source)){if(m.required)r.error(rows[0].line,m.source,"Required source column is missing");else r.warnings.push_back("Optional source column is absent: "+m.source);}}size_t omitted=0;for(auto&h:r.fields)if(!selected.count(h))++omitted;if(omitted)r.warnings.push_back(std::to_string(omitted)+" source column(s) are intentionally omitted by the mapping");std::ostringstream out;out<<"[\n";for(size_t i=1;i<rows.size();++i){if(i>1)out<<",\n";out<<"  {";for(size_t j=0;j<mapping.size();++j){auto&m=mapping[j];if(j)out<<", ";out<<jq(m.target)<<": ";auto p=index.find(m.source);if(p==index.end()||p->second>=rows[i].cells.size())out<<"null";else out<<typed(rows[i].cells[p->second],m,rows[i].line,r);}out<<'}';}out<<"\n]\n";if(r.errors.empty()){atomic_write(a.input,a.output,out.str());r.written=r.read;}}catch(const std::exception&e){r.error(0,"",e.what());}r.print();return r.errors.empty()?0:2;}
